const input = $input.first().json;

const required = [
  'schema_version',
  'alert_id',
  'source',
  'category',
  'subtype',
  'status',
  'event_action',
  'title',
  'message',
  'priority'
];

const missing = required.filter((field) => {
  const value = input[field];
  return value === undefined || value === null || value === '';
});

if (missing.length) {
  throw new Error(`Standard Alert missing required field(s): ${missing.join(', ')}`);
}

const location = (input.location && typeof input.location === 'object')
  ? input.location
  : {};

const tags = Array.isArray(input.tags)
  ? input.tags
  : (input.tags ? [String(input.tags)] : []);

const searchParts = [
  input.source,
  input.category,
  input.subtype,
  input.status,
  input.county,
  input.municipality,
  location.label,
  location.address,
  input.title,
  input.message,
  ...tags
].filter((value) => value !== undefined && value !== null && String(value).trim() !== '');

return [{
  json: {
    ...input,
    location,
    tags,
    priority: Number(input.priority),
    search_text: searchParts.join(' ')
  }
}];

const alert = $('Normalize Alert').first().json;
const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => row && row.watch_id);

function normalize(value) {
  if (value === undefined || value === null) return '';

  let text;
  if (Array.isArray(value)) {
    text = value.join(' ');
  } else if (typeof value === 'object') {
    text = JSON.stringify(value);
  } else {
    text = String(value);
  }

  return text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .replace(/&/g, '')
    .replace(/[^A-Z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function toArray(value) {
  if (value === undefined || value === null || value === '') return [];
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value === 'string') {
    return value
      .split('|')
      .map((part) => part.trim())
      .filter(Boolean);
  }
  return [value];
}

function getPath(object, path) {
  if (!path) return undefined;
  return String(path)
    .split('.')
    .reduce((current, key) => {
      if (current === undefined || current === null) return undefined;
      return current[key];
    }, object);
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function evaluateRow(row) {
  const alertPriority = Number(alert.priority || 0);
  const minimumPriority = Number(row.min_priority || 1);

  if (alertPriority < minimumPriority) {
    return { matched: false, skip_reason: `priority ${alertPriority} < ${minimumPriority}` };
  }

  const sourceFilters = toArray(row.source_filter).map(normalize);
  if (sourceFilters.length && !sourceFilters.includes(normalize(alert.source))) {
    return { matched: false, skip_reason: 'source filter' };
  }

  const categoryFilters = toArray(row.alert_category_filter).map(normalize);
  if (categoryFilters.length && !categoryFilters.includes(normalize(alert.category))) {
    return { matched: false, skip_reason: 'category filter' };
  }

  const matchField = row.match_field || 'search_text';
  const haystack = normalize(getPath(alert, matchField));
  const candidates = [
    { value: row.search_term, kind: 'search_term' },
    ...toArray(row.aliases).map((value) => ({ value, kind: 'alias' }))
  ]
    .map((candidate) => ({
      ...candidate,
      normalized: normalize(candidate.value)
    }))
    .filter((candidate) => candidate.normalized);

  const mode = normalize(row.match_mode);

  for (const candidate of candidates) {
    let isMatch = false;

    if (mode === 'FIELD' || mode === 'EXACT') {
      isMatch = haystack === candidate.normalized;
    } else if (mode === 'CONTAINS') {
      isMatch = haystack.includes(candidate.normalized);
    } else if (mode === 'WORD') {
      const pattern = new RegExp(
        `(^|\\s)${escapeRegExp(candidate.normalized)}(?=\\s|$)`
      );
      isMatch = pattern.test(haystack);
    }

    if (isMatch) {
      return {
        matched: true,
        matched_candidate: candidate.value,
        matched_candidate_type: candidate.kind,
        match_field: matchField,
        match_reason:
          `${mode} ${matchField} matched ${candidate.kind} "${candidate.value}"`
      };
    }
  }

  return { matched: false };
}

const matches = [];
const recipientMap = new Map();

for (const row of rows) {
  const result = evaluateRow(row);
  if (!result.matched) continue;

  const match = {
    watch_item_uuid: row.watch_item_uuid || row.id || null,
    watch_id: row.watch_id,
    display_name: row.display_name,
    watch_type: row.watch_type,
    match_mode: row.match_mode,
    match_field: result.match_field,
    matched_candidate: result.matched_candidate,
    matched_candidate_type: result.matched_candidate_type,
    match_reason: result.match_reason
  };

  matches.push(match);

  const recipients = toArray(row.recipients);
  for (const recipient of recipients) {
    if (!recipient || typeof recipient !== 'object') continue;
    if (!recipient.subscriber_id && !recipient.ntfy_topic) continue;

    const key = recipient.subscriber_id || recipient.ntfy_topic;

    if (!recipientMap.has(key)) {
      recipientMap.set(key, {
        subscriber_uuid: recipient.subscriber_uuid || null,
        subscriber_id: recipient.subscriber_id || null,
        name: recipient.name || null,
        ntfy_topic: recipient.ntfy_topic || null,
        matched_watch_ids: [],
        match_reasons: []
      });
    }

    const resolved = recipientMap.get(key);

    if (!resolved.matched_watch_ids.includes(row.watch_id)) {
      resolved.matched_watch_ids.push(row.watch_id);
    }

    if (!resolved.match_reasons.includes(result.match_reason)) {
      resolved.match_reasons.push(result.match_reason);
    }
  }
}

const recipients = Array.from(recipientMap.values());

const delivery_payloads = recipients.map((recipient) => ({
  alert_id: alert.alert_id,
  subscriber_id: recipient.subscriber_id,
  subscriber_name: recipient.name,
  ntfy_topic: recipient.ntfy_topic,
  title: alert.title,
  message: alert.message,
  priority: alert.priority,
  tags: alert.tags || [],
  click: alert.click_url || '',
  matched_watch_ids: recipient.matched_watch_ids,
  match_reasons: recipient.match_reasons
}));

return [{
  json: {
    alert,
    matched: matches.length > 0,
    match_count: matches.length,
    recipient_count: recipients.length,
    matched_watch_ids: matches.map((match) => match.watch_id),
    matches,
    recipients,
    delivery_payloads
  }
}];
